"""Build a screenshot-led search desk, using the existing lab chrome."""
from pathlib import Path
from copy import deepcopy
from bs4 import BeautifulSoup
from html import escape
from lab_links import oria

NVA = 'https://www.sikt.no/tjenester/nasjonalt-vitenarkiv-nva/hjelpeside-nva/brukerveiledninger-nva/sok-i-nva'
SCHOLAR = 'https://scholar.google.com/intl/en/scholar/help.html'
UIB = 'https://www4.uib.no/en/university-library/using-the-library/the-librarys-discovery-service-oria'
ARCHIVE = 'https://help.archive.org/help/accounts-a-basic-guide/'
TIBI = 'https://tibi.no/hjelp/apper-og-avspillere/tibi-appen/'

def figure(name, alt, caption, source, label, phone=False):
    from PIL import Image
    root=Path(__file__).resolve().parents[1]
    width,height=Image.open(root/'labs/research-assets'/name).size
    return f'''<figure class="rp-shot{' rp-phone' if phone else ''}"><a href="research-assets/{name}" target="_blank" rel="noopener" aria-label="Enlarge screenshot: {escape(alt,quote=True)}"><img src="research-assets/{name}" alt="{escape(alt,quote=True)}" width="{width}" height="{height}" loading="lazy"/></a><figcaption>{caption} <a href="{source}" target="_blank" rel="noopener">{label} ↗</a>. Select the image to enlarge.</figcaption></figure>'''

def build(root):
    source=BeautifulSoup((root/'labs/academic-library.html').read_text(encoding='utf-8'),'html.parser')
    page=BeautifulSoup('''<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Find research, step by step | Turing's Library</title><meta name="description" content="Real screenshots and small steps for Google Scholar, Sikt NVA, UiB Oria, Internet Archive and Tibi audiobooks."/><link rel="stylesheet" href="studio.css?v=3"/><link rel="stylesheet" href="halloween-library.css?v=3"/><link rel="stylesheet" href="research-guide.css?v=1"/><link rel="stylesheet" href="accessibility.css?v=contrast20261009"/><script defer src="accessibility.js?v=1"></script><script defer src="research-guide.js?v=1"></script></head><body class="studio page-research-guide hl-season"><a class="access-skip" href="#main-content">Skip to main content</a><main id="main-content" tabindex="-1"></main></body></html>''','html.parser')
    page.main.insert_before(deepcopy(source.select_one('.studio-header')))
    page.main.insert_before(deepcopy(source.select_one('.access-bar')))
    nva1=figure('nva-image2.png','NVA search bar with Result, Persons and Project choices.','Choose Result for publications or Persons for a researcher. The English interface is shown; the sample result is from another field.',NVA,'Sikt search guide, September 2025')
    nva2=figure('nva-image6.png','NVA Filter panel with Category, Academic article, Institution and Contributor.','Use Category to narrow the publication type. Counts in this guide image are examples.',NVA,'Sikt search guide, September 2025',True)
    scholar=figure('scholar-results.jpg','Google Scholar results with PDF and HTML links on the right, and All versions below results.','Screenshot from Moudhi Almutairi’s Kuwait University HSC Library guide. This older example shows PDF/HTML and All versions. The subject is enzymes; use your own project words. Layout and dates can differ today.',SCHOLAR,"Google's current search help",True)
    account=figure('archive-account.png','Internet Archive account form: email, public screen name, password and account verification.','Official account-creation example, published in 2022. Follow the labels on the current form.',ARCHIVE,'Internet Archive Help Center')
    login=figure('archive-login.png','Internet Archive Sign In menu with the Log In option.','The account menu leads to Log In. This is Internet Archive’s own login.',ARCHIVE,'Internet Archive Help Center')
    shelf=figure('tibi-shelf.png','Tibi Bokhylle with three-dot book menus and an arrow marking a downloaded audiobook.','Bokhylle means bookshelf. The marked arrow shows a downloaded book. Example loans and dates belong to Tibi’s demonstration.',TIBI,'Tibi official app guide',True)
    player=figure('tibi-player.png','Tibi audiobook with text, player controls and a three-dot menu.','Open a book from your shelf to listen. Some books include text alongside the audio.',TIBI,'Tibi official app guide',True)
    content=f'''<header class="rp-hero" id="search-start"><div><nav class="wf-library-trail" aria-label="Back to your lab"><a href="lab-programme.html#all-labs">Original lab map</a><a class="rp-back" href="academic-library.html#ls-find">← Back to room 3: Find a source</a></nav><p class="rp-kicker">TURING'S LIBRARY / THE SEARCH DESK</p><h1>Follow your idea.<br/>Find a source.</h1><p>Made something? Bring one question about it. Start with two or three search words, find one useful source, then take the idea back into your work.</p><p class="rp-example"><b>My game lets someone choose a path.</b><br/>Try <code>player agency games</code>. For a story, try <code>interactive fiction choice</code>. Add <code>belonging</code> if that is your theme.</p></div><img src="turing-halloween-library.svg" alt="" width="1200" height="620"/></header>
<section class="rp-chooser" aria-labelledby="rp-choose"><p class="rp-kicker">PICK ONE DOOR. YOU DO NOT NEED ALL FIVE.</p><h2 id="rp-choose">What do you need right now?</h2><nav aria-label="Choose a research route"><a href="#scholar"><span>01 / ARTICLES</span><strong>Google Scholar</strong><small>Search a topic across research fields. Start here if unsure.</small></a><a href="#nva"><span>02 / NORWEGIAN RESEARCH</span><strong>Sikt / NVA</strong><small>Find a Norwegian researcher, publication or available file.</small></a><a href="#uib-access"><span>03 / BOOKS &amp; ACCESS</span><strong>UiB / Oria</strong><small>Find a real shelf or open something UiB subscribes to.</small></a><a href="#internet-archive"><span>04 / DIGITISED MATERIAL</span><strong>Internet Archive</strong><small>Explore scans, older books and other archived material.</small></a><a href="#tibi"><span>05 / LISTENING</span><strong>Tibi audiobooks</strong><small>Adapted reading for eligible borrowers.</small></a></nav><p class="rp-small">Service links open in another tab so these instructions stay here. Screenshots come from the linked official guides, not a live capture of your account. Some show older layouts.</p></section>
<details class="rp-station" id="scholar" open><summary><span>01</span><div><small>THE ARTICLE DESK</small><h2>Search Google Scholar</h2></div><b aria-hidden="true">+</b></summary><div class="rp-body"><p class="rp-account">Account: begin with a public search. A Google account is used for personal features such as your saved library.</p><form class="rp-search" action="https://scholar.google.com/scholar" target="_blank" method="get" rel="noopener"><label for="rp-query">Words from your project<input id="rp-query" name="q" type="search" value="player agency games" required/></label><button type="submit">Open this Scholar search ↗</button></form><div class="rp-split"><div><ol class="rp-steps"><li><b>Search a small question.</b> Start with two or three terms. Too many results? Add a theme. Nothing useful? Remove a word or try a synonym.</li><li><b>Read one result.</b> Check title, authors, year and publication. Open the title and read the abstract, the short summary. Does it address your question?</li><li><b>Find the actual text.</b> Try a <b>[PDF]</b> or <b>[HTML]</b> link beside the result. No file? Select <b>All versions</b>. For library access, follow the <a href="#uib-access">UiB route below</a>.</li><li><b>Follow a useful lead.</b> <b>Cited by</b> finds works citing this source; <b>Related articles</b> finds similar material. Neither is a quality score. Read the source before citing it.</li></ol><p>Need an exact title? Put it in quotation marks. Newer research? Use the year filters. Older work can still be relevant.</p><p><a href="{SCHOLAR}" target="_blank" rel="noopener">Google's search and access help ↗</a></p></div>{scholar}</div><a class="rp-next" href="#use-source">Found something? Bring it back to your project →</a></div></details>
<details class="rp-station" id="nva"><summary><span>02</span><div><small>SIKT'S NATIONAL RESEARCH ARCHIVE</small><h2>Find research in NVA</h2></div><b aria-hidden="true">+</b></summary><div class="rp-body"><p class="rp-account">Account: no login needed to search NVA.</p><p><a class="rp-launch" href="https://nva.sikt.no/" target="_blank" rel="noopener">Open NVA at nva.sikt.no ↗</a> · <a href="https://www.sikt.no/" target="_blank" rel="noopener">About Sikt ↗</a></p><ol class="rp-steps"><li><b>Choose what you want to find.</b> Beside the search box, choose <b>Result</b> for publications, <b>Persons</b> for researchers or <b>Project</b> for research projects.</li><li><b>Type a title, theme or name.</b> Try <code>game interfaces</code>. Or choose Persons and try <code>Kristine Jørgensen</code>, then check the institution on the matching profile.</li></ol>{nva1}<div class="rp-split"><div><ol class="rp-steps" start="3"><li><b>Narrow the results.</b> Open <b>Filter</b>. Choose a relevant category, such as <b>Academic article</b>. Add an institution if useful. Use the file filter when you need an uploaded text.</li><li><b>Open a publication record.</b> Check author, year, type and summary. Open an available file or follow the publication link. Some records have no readable file.</li><li><b>Keep a route back.</b> Save the record link or DOI, then read the text. A record in NVA alone does not establish peer review.</li></ol><p><a href="{NVA}" target="_blank" rel="noopener">Sikt's full search instructions ↗</a> · <a href="https://cms.sikt.no/sites/default/files/2025-09/NVA-help_Search_EN_300925.docx" target="_blank" rel="noopener">Illustrated English guide (.docx) ↗</a></p></div>{nva2}</div><a class="rp-next" href="#use-source">Take the source back to your work →</a></div></details>
<details class="rp-station" id="uib-access"><summary><span>03</span><div><small>YOUR UNIVERSITY LIBRARY</small><h2>Find a book. Open the full text.</h2></div><b aria-hidden="true">+</b></summary><div class="rp-body"><p class="rp-account">Account: UiB / Feide for library borrowing and reservations. Searching Oria is open to everyone.</p><ol class="rp-steps"><li><b>Open UiB's catalogue.</b> Go to <a href="{escape(oria(),quote=True)}" target="_blank" rel="noopener">UiB Oria ↗</a>. Type the title, author or a few topic words. Select a result.</li><li><b>Physical book?</b> Find <b>Get It / Finn og bestill</b>. Check the library, availability and complete shelf mark. Keep the record on your phone, then follow the shelf signs. Show it to library staff if you cannot find the book.</li><li><b>Borrow or reserve?</b> Use <b>Sign in / Logg på</b>, choose UiB / Feide when offered, and use your UiB account. Follow the record's request options.</li><li><b>Article or e-book?</b> Follow the record's full-text link. On a private device, connect to <a href="https://hjelpekort.app.uib.no/en/KI-0706.html" target="_blank" rel="noopener">UiB's VPN ↗</a> for licensed material, then reopen the link. UiB says eduroam alone does not give licence access.</li></ol><div class="rp-callout"><b>Starting in MittUiB?</b><p>Open your course and its reading-list link, then choose the title. MittUiB is the course platform. The library provides access to the book or article.</p><a href="https://www4.uib.no/for-studenter/verktoy-og-tjenester/finn-litteraturlister" target="_blank" rel="noopener">UiB: find your course reading list ↗</a></div><p><a href="https://www.iorad.com/player/2516066/Find-physical-materials?isStaticShare=true" target="_blank" rel="noopener">UiB's real screenshot walkthrough: find physical materials ↗</a> · <a href="{UIB}" target="_blank" rel="noopener">UiB login and access instructions ↗</a></p><p class="rp-small">The screenshot walkthrough opens UiB's own guide. If access still fails, show the title or DOI to library staff. An Oria record does not guarantee full text.</p><a class="rp-next" href="academic-library.html#ls-find">Back to the shelves and the book's index →</a></div></details>
<details class="rp-station" id="internet-archive"><summary><span>04</span><div><small>THE DIGITISED COLLECTION</small><h2>Use Internet Archive</h2></div><b aria-hidden="true">+</b></summary><div class="rp-body"><p class="rp-account"><b>Internet Archive has its own account.</b> You do not log in through MittUiB or Feide. Using a student email address does not give UiB subscription access here.</p><ol class="rp-steps"><li><b>Search first.</b> Open <a href="https://archive.org/" target="_blank" rel="noopener">archive.org ↗</a>, search a title or author, and open an item. Check the edition and what is actually readable.</li><li><b>Need an account?</b> Follow <a href="https://archive.org/account/signup" target="_blank" rel="noopener">Sign up ↗</a>. Enter an email you can open, choose a public screen name and an Internet Archive password. Complete verification and confirm the email when asked.</li></ol>{account}<ol class="rp-steps" start="3"><li><b>Return and log in.</b> Use <a href="https://archive.org/account/login" target="_blank" rel="noopener">Log In ↗</a> with your Internet Archive account.</li><li><b>Read what is available.</b> Follow the item's reading or borrowing controls. <b>Borrow Unavailable</b> means the book cannot currently be borrowed. Try UiB Oria for another route.</li></ol>{login}<p><a href="{ARCHIVE}" target="_blank" rel="noopener">Official account guide ↗</a> · <a href="https://help.archive.org/help/why-are-so-many-books-listed-as-borrow-unavailable-at-the-internet-archive/" target="_blank" rel="noopener">Why borrowing may be unavailable ↗</a></p><a class="rp-next" href="#use-source">Use the edition you actually read →</a></div></details>
<details class="rp-station" id="tibi"><summary><span>05</span><div><small>THE LISTENING ROOM</small><h2>Read with the Tibi app</h2></div><b aria-hidden="true">+</b></summary><div class="rp-body"><p class="rp-account">Account: a Tibi borrower number and PIN. A UiB student account alone does not give access.</p><p>Tibi is adapted literature for people who have difficulty reading visual text because of a disability or illness. Check <a href="https://tibi.no/hvem-kan-lane/vilkar-for-innmelding-bm/" target="_blank" rel="noopener">who can borrow ↗</a> and apply through <a href="https://tibi.no/" target="_blank" rel="noopener">Bli låner at tibi.no ↗</a> if this fits you.</p><ol class="rp-steps"><li><b>Install Tibi.</b> Open the official <a href="https://apps.apple.com/no/app/tibi-library/id603112511" target="_blank" rel="noopener">iOS App Store ↗</a> or <a href="https://play.google.com/store/apps/details?id=com.nlb.android" target="_blank" rel="noopener">Android Google Play ↗</a> listing.</li><li><b>Log in.</b> Use your Tibi borrower number and PIN, supplied through registration. For a forgotten PIN, follow the reset instructions in <a href="{TIBI}" target="_blank" rel="noopener">Tibi's app help ↗</a>.</li><li><b>Search and borrow.</b> Choose <b>Søk</b>, type a title, author or theme, open a book and choose <b>Lån boka</b>. Available books appear in <b>Bokhylle</b>.</li><li><b>Download and listen.</b> On the shelf, open the book's three dots, choose <b>Last ned</b> and confirm. An arrow marks the downloaded book. Tap the book to play it offline.</li></ol><div class="rp-shots">{shelf}{player}</div><p>Some study books have restricted access. <a href="https://tibi.no/hjelp/lanergruppe/student/" target="_blank" rel="noopener">Tibi's student guide ↗</a> explains availability and how to identify the adapted edition for your citation.</p><a class="rp-next" href="#use-source">Bring the idea you listened to back to your work →</a></div></details>
<section class="rp-finish" id="use-source"><p class="rp-kicker">BACK AT THE MAKING TABLE</p><h2>One source. One new way to look.</h2><p>Read or listen to the relevant argument in context. What does it help you understand about your creation? Try a change, question a choice or explain an effect you can now see.</p><p>Keep the author, year, title and the edition you used. For an article, also keep the journal, volume, issue, pages and DOI. Record the page or locator for the passage you use. Check the publication type and the journal's review policy if you need a peer-reviewed article.</p><div class="rp-exits"><a href="academic-library.html#ls-connect">Return to room 4: Find meaning →</a><a href="academic-library.html#chicago-author-date">Chicago author-date examples →</a><a href="lab-programme.html#lab-5-workbench">Back to making →</a></div></section>'''
    for node in list(BeautifulSoup(content,'html.parser').contents): page.main.append(node)
    (root/'labs/research-guide.html').write_text(str(page),encoding='utf-8',newline='\n')

if __name__=='__main__': build(Path(__file__).resolve().parents[1])
